/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: db, code, request
 *   Constants: admin, user, album, artist, track, flags, previous
 *   Variables: harness, server, base, token, userToken
 * Tests
 *   - malformed legacy editor values become bounded repairable fields without rewriting source records
 *   - admin snapshots deny ordinary users, anonymous and revoked roles and expose allowlisted fields
 *   - metadata patches detect legacy changes and replay the exact saved intent
 *   - visibility needs only the admin role, inherits without storing cascades, and rejects external-art migration gaps
 *   - Credits updates retain the canonical primary Artist membership and reject arbitrary fields
 *   - one Page placement visibility is independent of its reused collection and order
 *   - private Page snapshots identify ready, missing and unsupported definitions with allowlisted metadata
 *   - placement visibility approval detects referenced title or source changes before committing
 *   - missing placement definition remains explicitly hideable without inventing a display name
 *   - private previews bind cookie viewers and current sessions while hidden public delivery stays denied
 *   - private preview cannot pin missing or weak object validators
 *   - legacy HTTPS artwork uses only the private allowlisted path for hidden Album snapshots and bytes
 *   - legacy artwork rechecks role, session, readiness and exact URL after the external read
 *   - legacy internal image paths still require exact ready image ownership and never bypass invalid explicit IDs
 *   - legacy external artwork failures stay private and never reveal the source or error details
 *   - a Track Number edit reorders existing members atomically and rejects invalid dates
 *   - hidden Follow targets and inherited releases are excluded before dynamic limits
 * @end-catalog */

import assert from 'node:assert/strict';
import { randomUUID } from 'node:crypto';
import type { Server } from 'node:http';
import { after, before, beforeEach, test } from 'node:test';
import { ObjectId } from 'mongodb';
import { createApp } from '../../src/app';
import { getDb } from '../../src/infrastructure/database';
import { editAdminCatalogItem, editAdminPageItem, getAdminCatalogItem, getAdminPage, listAdminCatalog } from '../../src/administration/catalog/adminCatalogService';
import { createSession } from '../../src/services/auth/authSessionService';
import { getListenerAlbum } from '../../src/services/listener/listenerContentService';
import { followArtist } from '../../src/services/listener/artistFollowService';
import { resolveFollowedArtistReleases } from '../../src/services/listener/followedArtistReleasesService';
import { Carousel } from '../../src/models/carousel';
import { getS3 } from '../../src/infrastructure/s3';
import { Readable } from 'node:stream';
import { legacyCatalogArtwork } from '../../src/administration/catalog/adminLegacyArtwork';
import { startMongoReplicaSet, type MongoReplicaSetHarness } from '../support/mongoReplicaSet';

let harness: MongoReplicaSetHarness, server: Server, base = '', token = '', userToken = '';
const admin = new ObjectId(), user = new ObjectId(), album = new ObjectId(), artist = new ObjectId(), track = new ObjectId();
const flags = ['FINITUDE_ARTIST_FOLLOWS_ENABLED'] as const;
const previous = Object.fromEntries(flags.map(key => [key, process.env[key]]));
const db = () => getDb()!;
const code = (expected: string) => (error: any) => error.code === expected;
const request = (path: string, body?: unknown, access = token) => fetch(base + path, {
    method: body === undefined ? 'GET' : 'PATCH', headers: { ...(access ? { Authorization: `Bearer ${access}` } : {}), 'Content-Type': 'application/json' },
    ...(body === undefined ? {} : { body: JSON.stringify(body) })
});
before(async () => {
    harness = await startMongoReplicaSet('archtree-admin-catalog-test');
    server = await new Promise(resolve => { const active = createApp().listen(0, '127.0.0.1', () => resolve(active)); });
    const address = server.address(); assert.ok(address && typeof address !== 'string'); base = `http://127.0.0.1:${address.port}`;
});
beforeEach(async () => {
    for (const name of ['users', 'authSessions', 'artists', 'albums', 'audioTracks', 'imageAssets', 'pages', 'carousels', 'contentCollections', 'artistFollows', 'adminCatalogMutations']) await db().collection(name).deleteMany({});
    for (const key of flags) process.env[key] = 'true';
    const adminUser = { _id: admin, role: 'admin', emailVerified: true, email: 'catalog-admin@example.test' }, ordinary = { _id: user, role: 'user', emailVerified: true, email: 'catalog-user@example.test' };
    await db().collection('users').insertMany([adminUser, ordinary]);
    token = (await createSession(adminUser)).accessToken; userToken = (await createSession(ordinary)).accessToken;
    await db().collection('artists').insertOne({ _id: artist, name: 'Synthetic Artist', lifecycleStatus: 'ready', albumIds: [] });
    await db().collection('albums').insertOne({ _id: album, title: 'Synthetic Album', lifecycleStatus: 'ready', audioTrackIds: [track.toHexString()] });
    await db().collection('audioTracks').insertOne({ _id: track, title: 'Synthetic track', uploadStatus: 'ready', publicationStatus: 'ready', s3Key: track.toHexString(), albumId: album.toHexString() });
});
after(async () => {
    await new Promise<void>(resolve => server?.close(() => resolve())); await harness?.stop();
    for (const key of flags) { if (previous[key] === undefined) delete process.env[key]; else process.env[key] = previous[key]; }
});

test('malformed legacy editor values become bounded repairable fields without rewriting source records', async () => {
    const name = `${'x'.repeat(199)}😀`, bio = 'First\r\nSecond\u0000';
    await db().collection('artists').updateOne({ _id: artist }, { $set: { name, bio } });
    await db().collection('audioTracks').updateOne({ _id: track }, { $set: { trackNumber: 10000, title: 'Title\u0000\ud800' } });
    const artistItem = (await getAdminCatalogItem(admin.toHexString(), 'artist', artist.toHexString())).item;
    assert.equal(artistItem.fields.name, 'x'.repeat(199)); assert.equal(artistItem.fields.bio, 'First\nSecond');
    const trackItem = (await getAdminCatalogItem(admin.toHexString(), 'audioTrack', track.toHexString())).item;
    assert.equal(trackItem.fields.trackNumber, null); assert.equal(trackItem.fields.title, 'Title\ufffd');
    assert.equal((await db().collection('artists').findOne({ _id: artist }))!.name, name);
    assert.equal((await db().collection('audioTracks').findOne({ _id: track }))!.trackNumber, 10000);
});

test('admin snapshots deny ordinary users, anonymous and revoked roles and expose allowlisted fields', async () => {
    const path = `/api/admin/v1/catalog/album/${album}`;
    assert.equal((await request(path, undefined, '')).status, 401);
    assert.equal((await request(path, undefined, userToken)).status, 403);
    const response = await request(path); assert.equal(response.status, 200); assert.match(response.headers.get('cache-control')!, /no-store/);
    const wire = JSON.stringify(await response.json());
    assert.ok(wire.includes('Synthetic Album')); assert.equal(wire.includes('s3Key'), false); assert.equal(wire.includes('createdBy'), false);
    await db().collection('users').updateOne({ _id: admin }, { $set: { role: 'user' } });
    assert.equal((await request(path)).status, 403);
    await assert.rejects(getAdminCatalogItem(admin.toHexString(), 'album', album.toHexString()), code('ADMIN_PERMISSION_REQUIRED'));
});

test('metadata patches detect legacy changes and replay the exact saved intent', async () => {
    const initial = (await getAdminCatalogItem(admin.toHexString(), 'album', album.toHexString())).item;
    await db().collection('albums').updateOne({ _id: album }, { $set: { title: 'Concurrent synthetic edit' } });
    const body = { operationId: randomUUID(), expectedRevision: initial.revision, fields: { title: 'Reviewed title' } };
    await assert.rejects(editAdminCatalogItem(admin.toHexString(), 'album', album.toHexString(), body), code('ADMIN_CATALOG_REVISION_CONFLICT'));
    body.expectedRevision = (await getAdminCatalogItem(admin.toHexString(), 'album', album.toHexString())).item.revision;
    const saved = await editAdminCatalogItem(admin.toHexString(), 'album', album.toHexString(), body);
    assert.deepEqual(await editAdminCatalogItem(admin.toHexString(), 'album', album.toHexString(), body), saved);
    await assert.rejects(editAdminCatalogItem(admin.toHexString(), 'album', album.toHexString(), { ...body, fields: { title: 'Different intent' } }), code('ADMIN_CATALOG_IDEMPOTENCY_CONFLICT'));
    assert.deepEqual((await db().collection('albums').findOne({ _id: album }))?.audioTrackIds, [track.toHexString()]);
});

test('visibility needs only the admin role, inherits without storing cascades, and rejects external-art migration gaps', async () => {
    let item = (await getAdminCatalogItem(admin.toHexString(), 'album', album.toHexString())).item;
    const mutation = () => ({ operationId: randomUUID(), expectedRevision: item.revision, visibility: 'hidden' });
    await db().collection('albums').updateOne({ _id: album }, { $set: { coverArtUrl: 'https://example.test/old-public-art' } });
    item = (await getAdminCatalogItem(admin.toHexString(), 'album', album.toHexString())).item;
    await assert.rejects(editAdminCatalogItem(admin.toHexString(), 'album', album.toHexString(), mutation()), code('ADMIN_VISIBILITY_STORAGE_MIGRATION_REQUIRED'));
    await db().collection('albums').updateOne({ _id: album }, { $unset: { coverArtUrl: '' } });
    item = (await getAdminCatalogItem(admin.toHexString(), 'album', album.toHexString())).item;
    await editAdminCatalogItem(admin.toHexString(), 'album', album.toHexString(), mutation());
    assert.equal(await getListenerAlbum(album.toHexString()), null);
    const child = (await getAdminCatalogItem(admin.toHexString(), 'audioTrack', track.toHexString())).item;
    assert.equal(child.visibility, 'public'); assert.equal(child.effectiveVisibility, 'hidden');
    assert.equal((await db().collection('audioTracks').findOne({ _id: track }))?.visibility, undefined);
    assert.equal((await listAdminCatalog(admin.toHexString(), 'album', {})).items.length, 1);
});

test('Credits updates retain the canonical primary Artist membership and reject arbitrary fields', async () => {
    const initial = (await getAdminCatalogItem(admin.toHexString(), 'album', album.toHexString())).item;
    const body = { operationId: randomUUID(), expectedRevision: initial.revision, fields: { credits: [{ creditId: 'synthetic_credit', subjectType: 'artist', subjectId: artist.toHexString(), role: 'primary', order: 0 }], attributionStatus: 'documented' } };
    await editAdminCatalogItem(admin.toHexString(), 'album', album.toHexString(), body);
    assert.deepEqual((await db().collection('artists').findOne({ _id: artist }))?.albumIds, [album.toHexString()]);
    const current = (await getAdminCatalogItem(admin.toHexString(), 'album', album.toHexString())).item;
    await assert.rejects(async () => editAdminCatalogItem(admin.toHexString(), 'album', album.toHexString(), { operationId: randomUUID(), expectedRevision: current.revision, fields: { s3Key: 'untrusted' } }), code('ADMIN_CATALOG_INVALID_INPUT'));
});

test('one Page placement visibility is independent of its reused collection and order', async () => {
    const a = new ObjectId().toHexString(), b = new ObjectId().toHexString(), target = new ObjectId().toHexString();
    await db().collection('pages').insertOne({ slug: 'home', title: 'Home', items: [{ itemId: a, itemType: 'list', collectionId: target, order: 0 }, { itemId: b, itemType: 'list', collectionId: target, order: 1 }] });
    const page = (await getAdminPage(admin.toHexString(), 'home')).page;
    const body = { operationId: randomUUID(), expectedRevision: page.revision, visibility: 'hidden' };
    const saved = await editAdminPageItem(admin.toHexString(), 'home', a, body);
    assert.equal(saved.page.items[0].visibility, 'hidden'); assert.equal(saved.page.items[1].visibility, 'public');
    assert.deepEqual(saved.page.items.map(item => item.referenceId), [target, target]);
    assert.deepEqual(await editAdminPageItem(admin.toHexString(), 'home', a, body), saved);
});

test('private Page snapshots identify ready, missing and unsupported definitions with allowlisted metadata', async () => {
    const carousel = new ObjectId(), grid = new ObjectId(), incompatible = new ObjectId(), missing = new ObjectId();
    await db().collection('carousels').insertOne({ _id: carousel, name: 'Synthetic picks\u0000', mode: 'manual', items: [], createdBy: 'private-provenance' });
    await db().collection('contentCollections').insertMany([
        { _id: grid, name: 'Synthetic offline albums', mode: 'dynamic', presentation: 'grid', items: [], dynamicSource: 'downloadedAlbums', createdBy: 'private-provenance' },
        { _id: incompatible, name: 'Synthetic wrong presentation', mode: 'manual', presentation: 'grid' }
    ]);
    const items = [
        { itemId: new ObjectId().toHexString(), itemType: 'carousel', carouselId: carousel.toHexString(), order: 0 },
        { itemId: new ObjectId().toHexString(), itemType: 'grid', collectionId: grid.toHexString(), order: 1 },
        { itemId: new ObjectId().toHexString(), itemType: 'list', collectionId: incompatible.toHexString(), order: 2 },
        { itemId: new ObjectId().toHexString(), itemType: 'list', collectionId: missing.toHexString(), order: 3 }
    ];
    await db().collection('pages').insertOne({ slug: 'home', title: 'Synthetic Home', items });
    const result = await request('/api/admin/v1/pages/home'); assert.equal(result.status, 200);
    const wire = await result.json();
    assert.deepEqual(wire.page.items.map((item: any) => [item.name, item.sourceMode, item.referenceStatus]), [
        ['Synthetic picks', 'manual', 'ready'], ['Synthetic offline albums', 'dynamic', 'ready'],
        ['Synthetic wrong presentation', null, 'unsupported'], [null, null, 'missing']
    ]);
    const serialized = JSON.stringify(wire);
    assert.equal(serialized.includes('private-provenance'), false); assert.equal(serialized.includes('dynamicSource'), false);
    assert.equal((await request('/api/admin/v1/pages/home', undefined, userToken)).status, 403);
});

test('placement visibility approval detects referenced title or source changes before committing', async () => {
    const target = new ObjectId(), itemId = new ObjectId().toHexString();
    await db().collection('contentCollections').insertOne({ _id: target, name: 'Synthetic original list', mode: 'manual', presentation: 'list', items: [] });
    await db().collection('pages').insertOne({ slug: 'home', title: 'Synthetic Home', items: [{ itemId, itemType: 'list', collectionId: target.toHexString(), order: 0 }] });
    let initial = (await getAdminPage(admin.toHexString(), 'home')).page;
    await db().collection('contentCollections').updateOne({ _id: target }, { $set: { name: 'Synthetic renamed list' } });
    await assert.rejects(editAdminPageItem(admin.toHexString(), 'home', itemId, { operationId: randomUUID(), expectedRevision: initial.revision, visibility: 'hidden' }), code('ADMIN_CATALOG_REVISION_CONFLICT'));
    initial = (await getAdminPage(admin.toHexString(), 'home')).page;
    await db().collection('contentCollections').updateOne({ _id: target }, { $set: { mode: 'dynamic' } });
    await assert.rejects(editAdminPageItem(admin.toHexString(), 'home', itemId, { operationId: randomUUID(), expectedRevision: initial.revision, visibility: 'hidden' }), code('ADMIN_CATALOG_REVISION_CONFLICT'));
    const current = (await getAdminPage(admin.toHexString(), 'home')).page;
    const body = { operationId: randomUUID(), expectedRevision: current.revision, visibility: 'hidden' };
    const saved = await editAdminPageItem(admin.toHexString(), 'home', itemId, body);
    assert.equal(saved.page.items[0].name, 'Synthetic renamed list'); assert.equal(saved.page.items[0].sourceMode, 'dynamic');
    assert.equal(saved.page.items[0].visibility, 'hidden'); assert.equal((await db().collection('contentCollections').findOne({ _id: target }))!.name, 'Synthetic renamed list');
    assert.deepEqual(await editAdminPageItem(admin.toHexString(), 'home', itemId, body), saved);
});

test('missing placement definition remains explicitly hideable without inventing a display name', async () => {
    const itemId = new ObjectId().toHexString();
    await db().collection('pages').insertOne({ slug: 'home', title: 'Synthetic Home', items: [{ itemId, itemType: 'grid', collectionId: new ObjectId().toHexString(), order: Infinity }] });
    const current = (await getAdminPage(admin.toHexString(), 'home')).page;
    assert.equal(current.items[0].order, 0); assert.equal(current.items[0].referenceStatus, 'missing');
    const saved = await editAdminPageItem(admin.toHexString(), 'home', itemId, { operationId: randomUUID(), expectedRevision: current.revision, visibility: 'hidden' });
    assert.equal(saved.page.items[0].name, null); assert.equal(saved.page.items[0].visibility, 'hidden');
});

test('private previews bind cookie viewers and current sessions while hidden public delivery stays denied', async t => {
    await db().collection('albums').updateOne({ _id: album }, { $set: { visibility: 'hidden' } });
    t.mock.method(getS3(), 'send', async () => ({ ContentLength: 7, ETag: '"synthetic"', Body: Readable.from([Buffer.from('preview')]) }));
    const path = `/api/admin/v1/catalog/audioTrack/${track}/media`;
    const cookie = { Cookie: `session_token=${token}` };
    assert.equal((await fetch(base + path, { headers: cookie })).status, 409);
    assert.equal((await fetch(`${base}${path}?viewer=${user}`, { headers: cookie })).status, 409);
    const response = await fetch(`${base}${path}?viewer=${admin}`, { headers: cookie });
    assert.equal(response.status, 200); assert.equal(await response.text(), 'preview');
    assert.equal(response.headers.get('etag'), '"synthetic"');
    const head = await fetch(`${base}${path}?viewer=${admin}`, { method: 'HEAD', headers: cookie });
    assert.equal(head.status, 200); assert.equal(head.headers.get('etag'), '"synthetic"'); assert.equal(head.headers.get('accept-ranges'), 'bytes');
    assert.equal((await fetch(`${base}${path}?viewer=${admin}`, { headers: { ...cookie, 'If-Match': '"previous-object"', Range: 'bytes=0-2' } })).status, 412);
    assert.match(response.headers.get('cache-control')!, /no-store/);
    assert.equal(response.headers.get('x-finitude-account-viewer'), admin.toHexString());
    assert.equal((await request(`/content/mediaTrack/stream/${track}`)).status, 404);
    await db().collection('authSessions').updateMany({ userId: admin.toHexString() }, { $set: { revokedAt: new Date() } });
    assert.equal((await fetch(`${base}${path}?viewer=${admin}`, { headers: cookie })).status, 401);
});

test('private preview cannot pin missing or weak object validators', async t => {
    let etag: string | undefined;
    t.mock.method(getS3(), 'send', async () => ({ ContentLength: 7, ETag: etag, Body: Readable.from([Buffer.from('preview')]) }));
    const path = `${base}/api/admin/v1/catalog/audioTrack/${track}/media?viewer=${admin}`;
    for (etag of [undefined, 'W/"weak"']) assert.equal((await fetch(path, { method: 'HEAD', headers: { Cookie: `session_token=${token}` } })).status, 404);
});

test('legacy HTTPS artwork uses only the private allowlisted path for hidden Album snapshots and bytes', async t => {
    const legacy = 'https://images.example.test/private-album-cover.png?legacy=retained';
    await db().collection('albums').updateOne({ _id: album }, { $set: { visibility: 'hidden', coverArtUrl: legacy } });
    const item = (await getAdminCatalogItem(admin.toHexString(), 'album', album.toHexString())).item;
    const path = `/api/admin/v1/catalog/album/${album}/artwork`;
    assert.equal(item.coverUrl, path);
    const inventory = await listAdminCatalog(admin.toHexString(), 'album', {});
    assert.equal(inventory.items[0].coverUrl, path);
    assert.equal(JSON.stringify({ item, inventory }).includes(legacy), false);
    let calls = 0;
    t.mock.method(legacyCatalogArtwork, 'load', async (url: string, signal: AbortSignal) => {
        calls++; assert.equal(url, legacy); assert.equal(signal.aborted, false); return Buffer.from('decoded-webp');
    });
    assert.equal((await request(path, undefined, '')).status, 401);
    assert.equal((await request(path, undefined, userToken)).status, 403);
    assert.equal(calls, 0);
    const headers = { Cookie: `session_token=${token}` };
    assert.equal((await fetch(base + path, { headers })).status, 409);
    const response = await fetch(`${base}${path}?viewer=${admin}`, { headers });
    assert.equal(response.status, 200); assert.equal(await response.text(), 'decoded-webp');
    assert.equal(response.headers.get('content-type'), 'image/webp');
    assert.equal(response.headers.get('x-content-type-options'), 'nosniff');
    assert.match(response.headers.get('cache-control')!, /private, no-store/);
    assert.equal(response.headers.get('location'), null);
    const etag = response.headers.get('etag'); assert.ok(etag);
    const head = await fetch(`${base}${path}?viewer=${admin}`, { method: 'HEAD', headers });
    assert.equal(head.status, 200); assert.equal(head.headers.get('content-length'), '12'); assert.equal(head.headers.get('etag'), etag);
    const range = await fetch(`${base}${path}?viewer=${admin}`, { headers: { ...headers, Range: 'bytes=0-2', 'If-Match': etag } });
    assert.equal(range.status, 206); assert.equal(await range.text(), 'dec');
    assert.equal((await fetch(`${base}${path}?viewer=${admin}`, { headers: { ...headers, 'If-Match': '"older-image"' } })).status, 412);
    assert.equal(await getListenerAlbum(album.toHexString()), null);
});

test('legacy artwork rechecks role, session, readiness and exact URL after the external read', async t => {
    const path = `/api/admin/v1/catalog/album/${album}/artwork`;
    const legacy = 'https://images.example.test/original.png';
    const mutations = [
        () => db().collection('albums').updateOne({ _id: album }, { $set: { coverArtUrl: 'https://images.example.test/replaced.png' } }),
        () => db().collection('albums').updateOne({ _id: album }, { $set: { lifecycleStatus: 'deleting' } }),
        () => db().collection('users').updateOne({ _id: admin }, { $set: { role: 'user' } }),
        () => db().collection('authSessions').updateMany({ userId: admin.toHexString() }, { $set: { revokedAt: new Date() } })
    ];
    for (const mutate of mutations) {
        await db().collection('users').updateOne({ _id: admin }, { $set: { role: 'admin' } });
        await db().collection('authSessions').updateMany({ userId: admin.toHexString() }, { $unset: { revokedAt: '' } });
        await db().collection('albums').updateOne({ _id: album }, { $set: { lifecycleStatus: 'ready', coverArtUrl: legacy } });
        const mock = t.mock.method(legacyCatalogArtwork, 'load', async () => { await mutate(); return Buffer.from('must-not-deliver'); });
        const response = await request(path);
        assert.equal(response.status, 404); assert.equal(await response.text(), '');
        mock.mock.restore();
    }
});

test('legacy internal image paths still require exact ready image ownership and never bypass invalid explicit IDs', async t => {
    const imageId = new ObjectId();
    const path = `/api/admin/v1/catalog/album/${album}/artwork`;
    await db().collection('albums').updateOne({ _id: album }, { $set: { visibility: 'hidden', coverArtUrl: `/content/images/${imageId}` } });
    await db().collection('imageAssets').insertOne({ _id: imageId, ownerId: album.toHexString(), ownerType: 'album', uploadStatus: 'pending', s3Key: `images/${imageId}`, contentType: 'image/png' });
    let calls = 0;
    t.mock.method(getS3(), 'send', async () => { calls++; return { ContentLength: 7, ETag: '"stored-image"', Body: Readable.from([Buffer.from('preview')]) }; });
    assert.equal((await getAdminCatalogItem(admin.toHexString(), 'album', album.toHexString())).item.coverUrl, path);
    assert.equal((await request(path)).status, 404); assert.equal(calls, 0);
    await db().collection('imageAssets').updateOne({ _id: imageId }, { $set: { uploadStatus: 'ready', ownerId: artist.toHexString() } });
    assert.equal((await request(path)).status, 404); assert.equal(calls, 0);
    await db().collection('imageAssets').updateOne({ _id: imageId }, { $set: { ownerId: album.toHexString() } });
    const response = await request(path); assert.equal(response.status, 200); assert.equal(await response.text(), 'preview');
    await db().collection('albums').updateOne({ _id: album }, { $set: { coverArtId: 'invalid' } });
    assert.equal((await getAdminCatalogItem(admin.toHexString(), 'album', album.toHexString())).item.coverUrl, null);
    assert.equal((await request(path)).status, 404);
});

test('legacy external artwork failures stay private and never reveal the source or error details', async t => {
    const legacy = 'https://images.example.test/private-path.png?private=source';
    await db().collection('albums').updateOne({ _id: album }, { $set: { coverArtUrl: legacy } });
    t.mock.method(legacyCatalogArtwork, 'load', async () => { throw new Error(legacy); });
    const response = await request(`/api/admin/v1/catalog/album/${album}/artwork`);
    assert.equal(response.status, 404); assert.equal(await response.text(), '');
    assert.equal(response.headers.get('location'), null); assert.match(response.headers.get('cache-control')!, /no-store/);
});

test('a Track Number edit reorders existing members atomically and rejects invalid dates', async () => {
    const second = new ObjectId();
    await db().collection('audioTracks').insertOne({ _id: second, title: 'Synthetic second track', uploadStatus: 'ready', publicationStatus: 'ready', s3Key: second.toHexString(), albumId: album.toHexString(), trackNumber: 2 });
    await db().collection('albums').updateOne({ _id: album }, { $set: { audioTrackIds: [track.toHexString(), second.toHexString()] } });
    const initial = (await getAdminCatalogItem(admin.toHexString(), 'audioTrack', track.toHexString())).item;
    await editAdminCatalogItem(admin.toHexString(), 'audioTrack', track.toHexString(), { operationId: randomUUID(), expectedRevision: initial.revision, fields: { trackNumber: 3 } });
    assert.deepEqual((await db().collection('albums').findOne({ _id: album }))?.audioTrackIds, [second.toHexString(), track.toHexString()]);
    const current = (await getAdminCatalogItem(admin.toHexString(), 'audioTrack', track.toHexString())).item;
    const invalid = await request(`/api/admin/v1/catalog/audioTrack/${track}`, { operationId: randomUUID(), expectedRevision: current.revision, fields: { releaseDate: { year: 2025, month: 2, day: 30 } } });
    assert.equal(invalid.status, 400);
});

test('hidden Follow targets and inherited releases are excluded before dynamic limits', async () => {
    await followArtist(user.toHexString(), artist.toHexString());
    const now = new Date(), releaseDate = { year: now.getUTCFullYear(), month: now.getUTCMonth() + 1, day: now.getUTCDate() };
    const credits = [{ creditId: 'synthetic_credit', subjectType: 'artist', subjectId: artist.toHexString(), role: 'primary', order: 0 }];
    await db().collection('albums').updateOne({ _id: album }, { $set: { visibility: 'hidden', releaseDate, credits, attributionStatus: 'documented' } });
    await db().collection('audioTracks').updateOne({ _id: track }, { $set: { releaseDate, credits, attributionStatus: 'documented' } });
    assert.deepEqual(await resolveFollowedArtistReleases(user.toHexString(), 20, true, now), []);
    await db().collection('artists').updateOne({ _id: artist }, { $set: { visibility: 'hidden' } });
    await assert.rejects(followArtist(admin.toHexString(), artist.toHexString()), code('ARTIST_UNAVAILABLE'));
    const resolved = await Carousel.resolveCarousel({ mode: 'artist', artistConfig: { artistId: artist.toHexString(), contentType: 'album', sort: 'titleAsc', limit: 20 } });
    assert.deepEqual(resolved.items, []); assert.equal(resolved.artistConfig, undefined);
});
